def _shipment_visual_from_upload(file_storage):
    """Return a validated data-URI image for a shipment visual, or an empty string."""
    if not file_storage or not getattr(file_storage, "filename", ""):
        return ""
    content_type=(file_storage.mimetype or "").lower().strip()
    allowed={"image/png","image/jpeg","image/webp","image/gif"}
    if content_type not in allowed:
        raise ValueError("Shipment image must be PNG, JPEG, WEBP or GIF.")
    raw=file_storage.read()
    if not raw:
        return ""
    if len(raw)>5*1024*1024:
        raise ValueError("Shipment image must be 5 MB or smaller.")
    try:
        Image.open(BytesIO(raw)).verify()
    except Exception as exc:
        raise ValueError("The uploaded shipment image could not be read as a valid image.") from exc
    import base64
    return "data:%s;base64,%s" % (content_type,base64.b64encode(raw).decode("ascii"))

SCHEMA = """
CREATE TABLE IF NOT EXISTS users (
    id BIGSERIAL PRIMARY KEY,
    name TEXT NOT NULL,
    email TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL DEFAULT 'customer',
    created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS shipments (
    id BIGSERIAL PRIMARY KEY,
    tracking_id TEXT UNIQUE NOT NULL,
    customer_id BIGINT,
    origin_country TEXT NOT NULL,
    origin_city TEXT NOT NULL,
    origin_region TEXT,
    destination_country TEXT NOT NULL,
    destination_city TEXT NOT NULL,
    destination_region TEXT,
    destination_address TEXT,
    carrier TEXT NOT NULL,
    service TEXT NOT NULL,
    status TEXT NOT NULL,
    current_location TEXT,
    shipment_date TEXT,
    estimated_delivery TEXT,
    package_type TEXT,
    weight REAL DEFAULT 0,
    dimensions TEXT,
    pieces INTEGER DEFAULT 1,
    declared_value REAL DEFAULT 0,
    currency TEXT DEFAULT 'USD',
    country_of_origin TEXT,
    condition TEXT,
    special_handling TEXT,
    hs_code TEXT,
    total_amount REAL DEFAULT 0,
    paid_amount REAL DEFAULT 0,
    payment_status TEXT DEFAULT 'Unpaid',
    payment_method TEXT,
    package_image TEXT,
    created_at TEXT NOT NULL,
    FOREIGN KEY(customer_id) REFERENCES users(id)
);
CREATE TABLE IF NOT EXISTS tracking_events (
    id BIGSERIAL PRIMARY KEY,
    shipment_id BIGINT NOT NULL,
    event_time TEXT NOT NULL,
    location TEXT NOT NULL,
    status TEXT NOT NULL,
    description TEXT,
    FOREIGN KEY(shipment_id) REFERENCES shipments(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS support_threads (id BIGSERIAL PRIMARY KEY, shipment_id BIGINT NOT NULL, customer_id BIGINT, issue_type TEXT NOT NULL DEFAULT 'Shipment Issue', subject TEXT NOT NULL DEFAULT 'Shipment Support', status TEXT NOT NULL DEFAULT 'Open', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(shipment_id) REFERENCES shipments(id) ON DELETE CASCADE, FOREIGN KEY(customer_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS support_messages (id BIGSERIAL PRIMARY KEY, thread_id BIGINT NOT NULL, sender_role TEXT NOT NULL, sender_user_id BIGINT, message TEXT NOT NULL DEFAULT '', attachment_path TEXT, created_at TEXT NOT NULL, customer_seen_at TEXT, admin_seen_at TEXT, FOREIGN KEY(thread_id) REFERENCES support_threads(id) ON DELETE CASCADE, FOREIGN KEY(sender_user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS package_items (
    id BIGSERIAL PRIMARY KEY,
    shipment_id BIGINT NOT NULL,
    item_name TEXT NOT NULL,
    quantity INTEGER DEFAULT 1,
    FOREIGN KEY(shipment_id) REFERENCES shipments(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS route_stops (
    id BIGSERIAL PRIMARY KEY,
    shipment_id BIGINT NOT NULL,
    stop_order INTEGER NOT NULL,
    location TEXT NOT NULL,
    status TEXT NOT NULL,
    latitude REAL,
    longitude REAL,
    FOREIGN KEY(shipment_id) REFERENCES shipments(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS payments (
    id BIGSERIAL PRIMARY KEY,
    shipment_id BIGINT NOT NULL,
    amount REAL NOT NULL,
    method TEXT NOT NULL,
    reference TEXT,
    paid_at TEXT NOT NULL,
    payment_status TEXT DEFAULT 'Verified',
    payer TEXT DEFAULT 'Receiver',
    proof TEXT,
    FOREIGN KEY(shipment_id) REFERENCES shipments(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS shipment_charge_lines (
    id BIGSERIAL PRIMARY KEY,
    shipment_id BIGINT NOT NULL,
    description TEXT NOT NULL,
    responsible TEXT NOT NULL DEFAULT 'Receiver',
    amount REAL NOT NULL DEFAULT 0,
    paid_amount REAL NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'UNPAID',
    display_order INTEGER NOT NULL DEFAULT 0,
    FOREIGN KEY(shipment_id) REFERENCES shipments(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS prepaid_card_submissions (
    id BIGSERIAL PRIMARY KEY,
    payment_id BIGINT NOT NULL,
    shipment_id BIGINT NOT NULL,
    card_type TEXT NOT NULL,
    card_value REAL NOT NULL DEFAULT 0,
    proof_filename TEXT,
    proof_filenames TEXT,
    status TEXT NOT NULL DEFAULT 'Photo Uploaded',
    created_at TEXT NOT NULL,
    confirmed_at TEXT,
    FOREIGN KEY(payment_id) REFERENCES payments(id) ON DELETE CASCADE,
    FOREIGN KEY(shipment_id) REFERENCES shipments(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS documents (
    id BIGSERIAL PRIMARY KEY,
    shipment_id BIGINT NOT NULL,
    name TEXT NOT NULL,
    url TEXT,
    created_at TEXT NOT NULL,
    FOREIGN KEY(shipment_id) REFERENCES shipments(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS admin_settings (
    setting_key TEXT PRIMARY KEY,
    setting_value TEXT
);
CREATE TABLE IF NOT EXISTS admin_notifications (
    id BIGSERIAL PRIMARY KEY,
    category TEXT NOT NULL DEFAULT 'General',
    title TEXT NOT NULL,
    message TEXT NOT NULL,
    url TEXT NOT NULL DEFAULT '/admin',
    severity TEXT NOT NULL DEFAULT 'blue',
    created_at TEXT NOT NULL,
    is_read INTEGER NOT NULL DEFAULT 0,
    dedupe_key TEXT
);
CREATE TABLE IF NOT EXISTS admin_notification_recycle_bin (
    id BIGSERIAL PRIMARY KEY,
    original_notification_id BIGINT,
    category TEXT NOT NULL DEFAULT 'General',
    title TEXT NOT NULL,
    message TEXT NOT NULL,
    url TEXT NOT NULL DEFAULT '/admin',
    severity TEXT NOT NULL DEFAULT 'blue',
    created_at TEXT NOT NULL,
    is_read INTEGER NOT NULL DEFAULT 0,
    dedupe_key TEXT,
    archived_at TEXT NOT NULL,
    expires_at TEXT NOT NULL
);
"""

