@app.route("/admin/support")
def admin_support():
    if not admin_required(): return redirect(url_for("login"))
    conn=db(); ts=conn.execute("SELECT t.*,s.tracking_id,s.receiver_name FROM support_threads t JOIN shipments s ON s.id=t.shipment_id ORDER BY t.updated_at DESC").fetchall(); sid=request.args.get("thread",type=int); sel=None; msgs=[]
    if sid:
        sel=conn.execute("SELECT t.*,s.tracking_id,s.receiver_name,s.receiver_email,s.receiver_phone FROM support_threads t JOIN shipments s ON s.id=t.shipment_id WHERE t.id=?",(sid,)).fetchone()
        if sel:
            conn.execute("UPDATE support_messages SET admin_seen_at=? WHERE thread_id=? AND sender_role='customer' AND admin_seen_at IS NULL",(datetime.utcnow().isoformat(),sid))
            conn.commit()
        msgs=conn.execute("SELECT * FROM support_messages WHERE thread_id=? ORDER BY id",(sid,)).fetchall() if sel else []
    conn.close()
    if sid and sel:
        if request.args.get("partial")=="1": return jsonify({"html":_support_message_rows(msgs,"admin"),"latest_id":int(msgs[-1]["id"]) if msgs else 0})
        return _support_chat_page("Support Conversation","/admin/support", sel["receiver_name"] or "Receiver", f"{sel['tracking_id']} · {sel['issue_type']}", sel["status"], '', _support_message_rows(msgs,"admin"), url_for("admin_support_reply",thread_id=sel["id"]), url_for("admin_support",thread=sel["id"]))
    listing=''.join(f'<a class="support-thread-list-item" href="/admin/support?thread={t["id"]}"><strong>{html.escape(t["tracking_id"])}</strong><span>{html.escape(t["issue_type"])} · {html.escape(t["status"])}</span><small>{html.escape(t["receiver_name"] or "Receiver")}</small></a>' for t in ts) or '<div class="support-empty">No support conversations yet.</div>'
    return layout("Support Inbox",f'<div class="admin-shell"><section class="admin-top-card"><div><div class="eyebrow">Customer Service</div><h1>Support Inbox</h1><p>Message receivers about individual shipments.</p></div><a class="admin-secondary-action" href="/admin">← Dashboard</a></section><div class="support-thread-list">{listing}</div></div>')

@app.route("/admin/support/<int:thread_id>/reply",methods=["POST"])
def admin_support_reply(thread_id):
    if not admin_required(): return redirect(url_for("login"))
    msg=(request.form.get("message") or "").strip(); uploads=[x for x in request.files.getlist("image") if x and x.filename]; attachment_list=[]; conn=db(); allowed={"image/jpeg":"jpg","image/png":"png","image/webp":"webp","image/gif":"gif"}; now=datetime.utcnow().isoformat()
    for upload in uploads:
        mime=(upload.mimetype or "").lower()
        if mime not in allowed: continue
        os.makedirs(SUPPORT_UPLOAD_DIR,exist_ok=True); attachment=f"support_uploads/{secrets.token_hex(16)}.{allowed[mime]}"; upload.save(os.path.join(BASE_DIR,"static",attachment)); attachment_list.append(attachment)
    if msg or attachment_list:
        if attachment_list:
            for i,attachment in enumerate(attachment_list): conn.execute("INSERT INTO support_messages(thread_id,sender_role,sender_user_id,message,attachment_path,created_at) VALUES(?,?,?,?,?,?)",(thread_id,"admin",session.get("user_id"),msg if i==0 else "",attachment,now))
        else: conn.execute("INSERT INTO support_messages(thread_id,sender_role,sender_user_id,message,attachment_path,created_at) VALUES(?,?,?,?,?,?)",(thread_id,"admin",session.get("user_id"),msg,None,now))
        # Use the shipment's current receiver account as the notification owner.
        # The support thread keeps its original customer_id for conversation
        # ownership, but the shipment is the source of truth for the receiver
        # account that should see this new admin message.
        thread=conn.execute("SELECT s.customer_id,s.tracking_id FROM support_threads t JOIN shipments s ON s.id=t.shipment_id WHERE t.id=?",(thread_id,)).fetchone()
        if thread and thread["customer_id"]:
            create_user_notification(conn,thread["customer_id"],"Message","New Message",f"You have a new message regarding your shipment {thread['tracking_id']}.",f"/shipment/{urllib.parse.quote(str(thread['tracking_id']),safe='')}/support","blue",f"admin-message:{thread_id}:{now}")
        conn.execute("UPDATE support_threads SET status='Open',updated_at=? WHERE id=?",(now,thread_id)); conn.commit()
    conn.close()
    if request.headers.get("X-Requested-With")=="XMLHttpRequest": return jsonify({"ok":True})
    return redirect(url_for("admin_support",thread=thread_id))

