@app.route("/track")
def track():
    tracking=(request.args.get("tracking") or request.form.get("tracking") or "").strip()
    if not tracking:
        body="""<div class='card' style='max-width:760px;margin:auto'><div class='eyebrow'>Shipment tracking</div><h1>Track Your Shipment</h1><p class='card-subtitle'>Enter your tracking number to view the latest shipment information.</p><form method='get'><label>Tracking Number</label><input name='tracking' placeholder='Enter Tracking Number' required><button class='btn' type='submit'>Track Shipment</button></form></div>"""
        return layout("Track Shipment",body)
    s=get_shipment(tracking)
    if not s:
        flash("We could not find that tracking number.")
        return redirect(url_for("track"))
    homepage_tracking = (request.args.get("_home_tracking") or "") == "1"
    conn=db()
    # Homepage tracking submissions are an additional notification trigger.
    # The existing tracking-presence/session flow remains unchanged for every
    # other entry point, while a homepage submission creates an admin activity
    # notification every time the homepage form is submitted successfully.
    record_tracking_presence(conn,s,notify=not homepage_tracking)
    if homepage_tracking:
        create_admin_notification(
            conn,
            "Tracking",
            "Tracking page opened",
            f"{s['receiver_name'] or 'A receiver'} entered tracking number {s['tracking_id']}.",
            f"/admin/shipment/{urllib.parse.quote(str(s['tracking_id']),safe='')}",
            "blue",
            None,
        )
    conn.commit(); conn.close()
    if not tracking_available(s):
        body=f"""<div class='tracking-disabled-card'><div class='tracking-disabled-icon'>!</div><h1>Tracking Unavailable</h1><p>Tracking for <strong>{s['tracking_id']}</strong> is currently unavailable. Please contact YS Logistics support for assistance.</p><a class='btn' href='/'>Return Home</a></div>"""
        return layout("Tracking Unavailable",body)
    if shipment_has_support_issue(s):
        issue=html.escape(support_issue_type(s)); msg=html.escape(support_issue_message(s))
        updated=html.escape(s["support_issue_updated_at"] or "")
        issue_value=html.escape(support_issue_type(s))
        try:
            _dt=datetime.fromisoformat(str(updated).replace("Z","+00:00")) if updated else None
            issue_date=_dt.strftime("%d %b %Y, %H:%M") if _dt else "Latest update"
        except Exception:
            issue_date="Latest update"
        body=f"""<div class='shipment-issue-gate'><img class='shipment-hold-hero' src='{SHIPMENT_HOLD_BANNER_URI}' alt='YS Logistics warehouse shipment hold'><div class='shipment-issue-content'><div class='shipment-issue-alert'><div class='shipment-issue-danger-icon'>⚠</div><div class='eyebrow'>Important Shipment Update</div><h1>{issue_value}</h1><p>{msg}</p></div><div class='shipment-issue-tracking'><div class='shipment-issue-detail'><span>Tracking Number</span><strong>{html.escape(s["tracking_id"])}</strong></div><div class='shipment-issue-detail'><span>Issue Type</span><strong>{issue_value}</strong></div><div class='shipment-issue-detail'><span>Date</span><strong>{issue_date}</strong></div></div><div class='shipment-issue-actions'><a class='btn' href='/shipment/{s["tracking_id"]}/support'>💬 Contact Support</a><a class='btn secondary' href='/'>⌂ Back to Home</a></div><div class='shipment-issue-support-note'>We're here to help. Contact the support team for assistance and next steps.</div></div></div>"""
        return layout("Shipment Hold",body)
    if (s["address_confirmation_status"] or "Pending confirmation") != "Confirmed":
        return redirect(url_for("shipment_address_confirmation",tracking_id=s["tracking_id"],token=s["address_confirmation_token"] or ""))
    return redirect(url_for("shipment_overview",tracking_id=s["tracking_id"]))


