@app.route("/register", methods=["GET","POST"])
def register():
    # Customer self-registration is intentionally disabled. Existing customer
    # accounts can still log in normally, while the public site no longer offers
    # a Sign Up option.
    flash("Customer sign-up is currently unavailable. Please use Login or your shipment tracking number.")
    return redirect(url_for("login"))


@app.route("/login", methods=["GET","POST"])
def login():
    if request.method=="POST":
        email=request.form.get("email","").strip().lower(); password=request.form.get("password","")
        conn=db(); user=conn.execute("SELECT * FROM users WHERE email=?",(email,)).fetchone(); conn.close()
        if user and check_password_hash(user["password_hash"],password):
            session.clear()
            session["user_id"] = user["id"]
            # Keep the user signed in for 30 days unless they explicitly untick the box.
            session.permanent = request.form.get("remember") == "on"
            return redirect(url_for("admin" if user["role"]=="admin" else "dashboard"))
        flash("Invalid email or password.")
    body="""<div class='card' style='max-width:560px;margin:auto'><h1>Login</h1><form method='post'><label>Email</label><input type='email' name='email' required><label>Password</label><input type='password' name='password' required><label style='display:flex;align-items:center;gap:10px;margin:14px 0;cursor:pointer'><input type='checkbox' name='remember' checked style='width:auto'> Keep me signed in on this device</label><button class='btn'>Login</button></form><p class='small'>Demo customer: customer@example.com / Customer123!<br>Demo admin: admin@example.com / ChangeMe123!</p></div>"""
    return layout("Login",body)


@app.route("/logout")
def logout(): session.clear(); return redirect(url_for("home"))


@app.route("/dashboard")
def dashboard():
    u=current_user()
    if not u:return redirect(url_for("login"))
    conn=db(); shipments=conn.execute("SELECT * FROM shipments WHERE customer_id=? ORDER BY created_at DESC",(u["id"],)).fetchall(); conn.close(); owing=sum(max(0,float(s["outstanding_balance"] or 0)) for s in shipments)
    pending_shipments=[s for s in shipments if (s['address_confirmation_status'] or 'Pending confirmation') != 'Confirmed']
    address_actions=''.join(f"<div class='address-action-row'><div><strong>{s['tracking_id']}</strong><span>{s['origin_city']} → {s['destination_city']}</span></div><a class='btn success' href='/shipment/{s['tracking_id']}/address-confirmation'>Confirm Address</a></div>" for s in pending_shipments)
    address_banner=f"<div class='card address-confirm-highlight'><div class='eyebrow'>Action required</div><h2>Confirm Your Delivery Address</h2><p>Please check the delivery address recorded for each shipment. If it is correct, open the shipment and press <strong>Confirm Delivery Address</strong>.</p><div class='address-action-list'>{address_actions or '<strong class=\"confirmed-text\">✓ All delivery addresses are confirmed.</strong>'}</div></div>"
    body=f"<div class='card'><div class='eyebrow'>Customer Dashboard</div><h1>Welcome, {u['name']}</h1><div class='grid'><div><div class='small'>Shipments</div><div class='stat'>{len(shipments)}</div></div><div><div class='small'>Total Amount Owing</div><div class='stat'>USD {owing:,.2f}</div></div><div><div class='small'>Account</div><div class='stat'>Active</div></div></div></div>{address_banner}<div class='section'><h2>Your Shipments</h2><div class='table-wrap'><table class='table'><tr><th>Tracking ID</th><th>Sender / Origin</th><th>Receiver / Destination</th><th>Status</th><th>Balance</th><th>Address</th></tr>" + ''.join(f"<tr><td><strong>{s['tracking_id']}</strong><br><a href='/shipment/{s['tracking_id']}'>View shipment</a></td><td>{s['sender_name'] or '—'}<br>{s['origin_city']}, {s['origin_country']}</td><td>{s['receiver_name'] or u['name']}<br>{s['destination_city']}, {s['destination_country']}</td><td><span class='badge'>{s['status']}</span></td><td>{s['currency']} {max(0,float(s['total_amount'] or 0)-float(s['paid_amount'] or 0)):,.2f}</td><td>{('<a class="btn success" href="/shipment/'+s['tracking_id']+'/address-confirmation">Confirm Address</a>' if (s['address_confirmation_status'] or 'Pending confirmation') != 'Confirmed' else '<span class="confirmed-text">✓ Confirmed</span>')}</td></tr>" for s in shipments) + "</table></div></div>"
    return layout("Customer Dashboard",body)


def admin_required():
    u=current_user(); return u and u["role"]=="admin"


def _http_json(url, headers=None, timeout=12):
    req = urllib.request.Request(url, headers=headers or {"User-Agent": "YS Logistics/1.0 (route planning)"})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read().decode("utf-8"))


def _reverse_movement_place(shipment_id, lat, lng, fallback="Current Location"):
    try:
        lat=float(lat); lng=float(lng)
    except Exception:
        return fallback
    now=datetime.utcnow().timestamp()
    cached=_MOVEMENT_LOCATION_CACHE.get(int(shipment_id))
    if cached and now-cached[2] < 15 and abs(lat-cached[0])+abs(lng-cached[1]) < 0.02:
        return cached[3] or fallback
    try:
        url=("https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat="+urllib.parse.quote(str(lat))+"&lon="+urllib.parse.quote(str(lng))+"&zoom=10&addressdetails=1")
        data=_http_json(url,headers={"User-Agent":"YS Logistics route planner/1.0"},timeout=8)
        a=data.get("address") or {}
        place=(a.get("city") or a.get("town") or a.get("village") or a.get("municipality") or a.get("county") or a.get("state_district") or a.get("state") or "").strip()
        if not place:
            display=str(data.get("display_name") or "").strip(); place=display.split(",")[0].strip() if display else ""
        if place:
            _MOVEMENT_LOCATION_CACHE[int(shipment_id)]=(lat,lng,now,place)
            return place
    except Exception:
        pass
    return cached[3] if cached and cached[3] else fallback


def _google_geocode(address, api_key):
    q = urllib.parse.quote_plus(address)
    data = _http_json(f"https://maps.googleapis.com/maps/api/geocode/json?address={q}&key={urllib.parse.quote_plus(api_key)}")
    if data.get("status") != "OK" or not data.get("results"):
        raise ValueError("Google could not find that address.")
    result = data["results"][0]
    loc = result["geometry"]["location"]
    components = {c["types"][0]: c["long_name"] for c in result.get("address_components", []) if c.get("types")}
    return {"lat": float(loc["lat"]), "lng": float(loc["lng"]), "formatted": result.get("formatted_address", address),
            "city": components.get("locality") or components.get("postal_town") or components.get("administrative_area_level_2") or "",
            "region": components.get("administrative_area_level_1") or "", "country": components.get("country") or ""}


def _country_code_for_geocoding(address):
    text = str(address or "").casefold()
    try:
        candidates = sorted(COUNTRY_DATA, key=lambda c: len(str(c.get("name") or "")), reverse=True)
    except Exception:
        candidates = []
    for country in candidates:
        name = str(country.get("name") or "").strip()
        code = str(country.get("code") or "").strip().lower()
        if name and code and name.casefold() in text:
            return code
        # Common display-name variants used in the admin country picker.
        if name == "United States" and "usa" in text:
            return "us"
        if name == "United Kingdom" and "uk" in text:
            return "gb"
    return ""


def _nominatim_geocode(address):
    q = urllib.parse.quote_plus(address)
    country_code = _country_code_for_geocoding(address)
    country_filter = f"&countrycodes={urllib.parse.quote_plus(country_code)}" if country_code else ""
    url = f"https://nominatim.openstreetmap.org/search?format=jsonv2&limit=5&addressdetails=1&q={q}{country_filter}"
    data = _http_json(url, headers={"User-Agent": "YS Logistics route planner/1.0"})
    if not data:
        raise ValueError("OpenStreetMap could not find that address.")
    # Prefer a result whose returned country agrees with the country selected
    # in the admin form. This prevents ambiguous city names from producing a
    # route in the wrong country.
    selected_country = ""
    if country_code:
        for country in COUNTRY_DATA:
            if str(country.get("code") or "").strip().lower() == country_code:
                selected_country = str(country.get("name") or "").strip().casefold()
                break
    r = data[0]
    if selected_country:
        for candidate in data:
            candidate_country = str((candidate.get("address") or {}).get("country") or "").strip().casefold()
            if candidate_country == selected_country or candidate_country in selected_country or selected_country in candidate_country:
                r = candidate
                break
    addr = r.get("address", {})
    return {"lat": float(r["lat"]), "lng": float(r["lon"]), "formatted": r.get("display_name", address),
            "city": addr.get("city") or addr.get("town") or addr.get("village") or addr.get("municipality") or "",
            "region": addr.get("state") or addr.get("county") or "", "country": addr.get("country") or ""}


