def _geocode(address, api_key=""):
    address = (address or "").strip()
    if not address:
        raise ValueError("Enter an origin and destination address first.")
    if api_key:
        try:
            return _google_geocode(address, api_key), "Google Maps"
        except Exception:
            pass
    return _nominatim_geocode(address), "OpenStreetMap"


def _haversine_km(a, b):
    r = 6371.0088
    p1, p2 = math.radians(a["lat"]), math.radians(b["lat"])
    dp = math.radians(b["lat"] - a["lat"])
    dl = math.radians(b["lng"] - a["lng"])
    x = math.sin(dp/2)**2 + math.cos(p1) * math.cos(p2) * math.sin(dl/2)**2
    return r * 2 * math.asin(min(1, math.sqrt(x)))


def _road_route(a, b, api_key=""):
    if api_key:
        try:
            origin = urllib.parse.quote_plus(a["formatted"])
            destination = urllib.parse.quote_plus(b["formatted"])
            data = _http_json(f"https://maps.googleapis.com/maps/api/directions/json?origin={origin}&destination={destination}&mode=driving&key={urllib.parse.quote_plus(api_key)}")
            if data.get("status") == "OK" and data.get("routes"):
                leg = data["routes"][0]["legs"][0]
                return float(leg["distance"]["value"])/1000.0, float(leg["duration"]["value"])/60.0, "Google Maps driving directions"
        except Exception:
            pass
    try:
        url = f"https://router.project-osrm.org/route/v1/driving/{a['lng']},{a['lat']};{b['lng']},{b['lat']}?overview=false"
        data = _http_json(url)
        if data.get("code") == "Ok" and data.get("routes"):
            route = data["routes"][0]
            return float(route["distance"])/1000.0, float(route["duration"])/60.0, "OpenStreetMap / OSRM road routing"
    except Exception:
        pass
    return _haversine_km(a,b), None, "Coordinate distance fallback"


def generate_route_data(origin_address, destination_address, mode, api_key=""):
    a, geocode_source_a = _geocode(origin_address, api_key)
    b, geocode_source_b = _geocode(destination_address, api_key)
    mode = (mode or "Air Freight").strip()
    if mode == "Road Freight":
        distance, duration, route_source = _road_route(a, b, api_key)
        summary = f"Road freight route: {a['formatted']} → {b['formatted']}"
    elif mode == "Air Freight":
        distance = _haversine_km(a,b)
        duration = max(60.0, (distance / 800.0) * 60.0)
        route_source = f"{geocode_source_a} / {geocode_source_b} air-distance estimate"
        summary = f"Air freight corridor: {a['formatted']} → {b['formatted']}"
    elif mode == "Sea Freight":
        distance = _haversine_km(a,b)
        duration = None
        route_source = f"{geocode_source_a} / {geocode_source_b} coordinate estimate"
        summary = f"Sea freight corridor: {a['formatted']} → {b['formatted']} (port-to-port estimate)"
    else:
        distance = _haversine_km(a,b)
        duration = None
        route_source = f"{geocode_source_a} / {geocode_source_b} coordinate estimate"
        summary = f"Express route: {a['formatted']} → {b['formatted']}"
    transit_days=max(1,int(math.ceil(duration/1440.0))) if duration is not None else None
    return {"origin":a,"destination":b,"distance_km":round(distance,1),"duration_minutes":round(duration,0) if duration is not None else None,
            "estimated_transit_days":transit_days,"mode":mode,"route_source":route_source,"summary":summary}


@app.route("/admin/route/generate", methods=["POST"])
def admin_route_generate():
    if not admin_required():
        return {"ok":False,"error":"Administrator login required."}, 401
    conn=db(); settings={r["setting_key"]:r["setting_value"] for r in conn.execute("SELECT * FROM admin_settings").fetchall()}; conn.close()
    f=request.form
    try:
        data=generate_route_data(f.get("origin_address") or f.get("origin_city"), f.get("destination_address") or f.get("destination_city"), f.get("transport_mode") or settings.get("default_transport_mode","Air Freight"), settings.get("google_maps_api_key",""))
        return {"ok":True,"route":data}
    except Exception as exc:
        return {"ok":False,"error":str(exc)}, 400


@app.route("/api/shipment/<tracking_id>/payment-details-status")
def payment_details_status_api(tracking_id):
    s=get_shipment(tracking_id)
    if not s: return jsonify({"ok":False,"error":"Shipment not found."}),404
    try: payment_id=int(request.args.get("payment_id") or 0)
    except (TypeError,ValueError): payment_id=0
    conn=db(); payment=conn.execute("SELECT * FROM payments WHERE id=? AND shipment_id=?",(payment_id,s["id"])).fetchone() if payment_id else None
    if not payment: conn.close(); return jsonify({"ok":False,"error":"Payment request not found."}),404
    row=_payment_detail_request(conn,payment_id); status=str(row["status"] or "") if row else str(payment["payment_status"] or "")
    result={"ok":True,"payment_id":payment_id,"status":"ready" if status.lower()=="ready" else "waiting"}
    conn.close(); response=jsonify(result); response.headers["Cache-Control"]="no-store, no-cache, must-revalidate, max-age=0"; return response

@app.route("/api/admin/shipment-payment-requests")
def admin_shipment_payment_requests_api():
    if not admin_required(): return {"ok":False},401
    conn=db(); rows=conn.execute("""SELECT p.id,p.shipment_id,p.amount,p.method,p.reference,p.paid_at,p.payment_status,p.proof,r.status AS detail_status,s.tracking_id,s.currency,s.receiver_name,s.receiver_email FROM payments p JOIN shipments s ON s.id=p.shipment_id LEFT JOIN payment_detail_requests r ON r.payment_id=p.id ORDER BY p.id DESC LIMIT 100""").fetchall(); conn.close()
    response={"ok":True,"requests":[{"id":r["id"],"tracking_id":r["tracking_id"],"receiver":r["receiver_name"] or "Receiver","email":r["receiver_email"] or "","amount":float(r["amount"] or 0),"currency":r["currency"] or "USD","method":r["method"] or "Not selected","status":r["detail_status"] or r["payment_status"] or "Pending","proof":bool(r["proof"]),"paid_at":r["paid_at"] or ""} for r in rows]}
    result=make_response(response)
    result.headers["Cache-Control"]="no-store, no-cache, must-revalidate, max-age=0"
    result.headers["Pragma"]="no-cache"
    return result

@app.route("/admin/shipment-payment-requests")
def admin_shipment_payment_requests():
    if not admin_required(): return redirect(url_for("login"))
    conn=db()
    rows=conn.execute("""SELECT p.id,p.shipment_id,p.amount,p.method,p.reference,p.paid_at,p.payment_status,p.proof,r.status AS detail_status,s.tracking_id,s.currency,s.receiver_name,s.receiver_email FROM payments p JOIN shipments s ON s.id=p.shipment_id LEFT JOIN payment_detail_requests r ON r.payment_id=p.id ORDER BY p.id DESC LIMIT 100""").fetchall()
    conn.close()
    table_rows=[]
    for x in rows:
        detail_status=str(x["detail_status"] or "").strip()
        status=str(detail_status or x["payment_status"] or "Pending")
        if detail_status.lower()=="payment details requested":
            status_html=f'<a href="/admin/payment-detail-requests/{x["id"]}" style="font-weight:900;color:#f0a800;text-decoration:underline">Payment Details Requested — View Request</a>'
        elif status=="Payment Details Ready":
            status_html=f'<a href="/admin/payment-detail-requests/{x["id"]}" style="font-weight:900;color:#0a9b62;text-decoration:underline">Payment Details Ready — View</a>'
        elif status=="Proof Submitted" and x["proof"]:
            href=f'/admin/shipment-payment-requests/{x["id"]}/prepaid' if str(x["method"] or "").strip()=="Prepaid Card" else f'/admin/shipment-payment-requests/{x["id"]}/proof'
            status_html=f'<a href="{href}" style="font-weight:900;color:#0788ef;text-decoration:underline">Proof Submitted — View</a>'
        else:
            status_html=html.escape(status)
        table_rows.append(f'<tr><td><a href="/admin/shipment-payment-requests/{x["id"]}" style="font-weight:900;color:#0b3d67">{html.escape(str(x["tracking_id"] or ""))}</a></td><td>{html.escape(str(x["receiver_name"] or "Receiver"))}<br><small>{html.escape(str(x["receiver_email"] or ""))}</small></td><td><strong>{html.escape(str(x["currency"] or "USD"))} {float(x["amount"] or 0):,.2f}</strong></td><td>{html.escape(str(x["method"] or "Not selected"))}</td><td>{status_html}</td><td>{html.escape(str(x["paid_at"] or ""))}</td></tr>')
    table_html=''.join(table_rows) if table_rows else '<tr><td colspan="6" class="admin-empty">No shipment payment requests yet.</td></tr>'
    body='''<div class="admin-shell"><section class="admin-top-card"><div><div class="eyebrow">Shipment payments</div><h1>Payment Management</h1><p>Live receiver payment requests, selected methods, proof submissions and payment review status.</p></div><div class="admin-top-actions"><a class="admin-secondary-action" href="/admin/payment-proofs">Payment Proof Archive</a><a class="admin-secondary-action" href="/admin">← Admin Dashboard</a></div></section><section class="admin-section"><div class="admin-section-head"><div><div class="eyebrow">Live requests</div><h2>Shipment Payment Requests</h2></div><span id="payment-management-live-indicator" class="admin-info-note" style="margin:0;white-space:nowrap">● Live</span></div><div style="overflow:auto"><table class="shipment-payment-admin-table" style="width:100%;border-collapse:collapse;min-width:680px"><thead><tr><th>Tracking</th><th>Receiver</th><th>Amount</th><th>Method</th><th>Status</th><th>Time</th></tr></thead><tbody id="shipment-payment-requests-body">''' + table_html + '''</tbody></table></div><p class="admin-info-note" style="margin-bottom:0">● This payment management list checks for new or changed requests every second without reloading the page.</p></section></div><script>
(function(){
  const body=document.getElementById('shipment-payment-requests-body');
  const indicator=document.getElementById('payment-management-live-indicator');
  if(!body)return;
  let lastSignature='';
  let busy=false;
  const esc=function(value){
    return String(value==null?'':value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
  };
  const renderRows=function(rows){
    if(!rows.length)return '<tr><td colspan="6" class="admin-empty">No shipment payment requests yet.</td></tr>';
    return rows.map(function(x){
      const status=String(x.status||'Pending');
      let statusHtml=esc(status);
      if(status.toLowerCase()==='payment details requested'){statusHtml='<a href="/admin/payment-detail-requests/'+encodeURIComponent(x.id)+'" style="font-weight:900;color:#f0a800;text-decoration:underline">Payment Details Requested — View Request</a>';} else if(status.toLowerCase()==='payment details ready'){statusHtml='<a href="/admin/payment-detail-requests/'+encodeURIComponent(x.id)+'" style="font-weight:900;color:#0a9b62;text-decoration:underline">Payment Details Ready — View</a>';} else if(status.toLowerCase()==='proof submitted' && x.proof){
        const method=String(x.method||'').trim();
        const href=method==='Prepaid Card' ? '/admin/shipment-payment-requests/'+encodeURIComponent(x.id)+'/prepaid' : '/admin/shipment-payment-requests/'+encodeURIComponent(x.id)+'/proof';
        statusHtml='<a href="'+href+'" style="font-weight:900;color:#0788ef;text-decoration:underline">Proof Submitted — View</a>';
      }
      return '<tr><td><a href="/admin/shipment-payment-requests/'+encodeURIComponent(x.id)+'" style="font-weight:900;color:#0b3d67">'+esc(x.tracking_id||'')+'</a></td><td>'+esc(x.receiver||'Receiver')+'<br><small>'+esc(x.email||'')+'</small></td><td><strong>'+esc(x.currency||'USD')+' '+Number(x.amount||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})+'</strong></td><td>'+esc(x.method||'Not selected')+'</td><td>'+statusHtml+'</td><td>'+esc(x.paid_at||'')+'</td></tr>';
    }).join('');
  };
  const signature=function(rows){
    return JSON.stringify(rows.map(function(x){return [x.id,x.amount,x.method,x.status,x.proof,x.paid_at,x.tracking_id,x.receiver,x.email]}));
  };
  const schedule=function(){window.setTimeout(poll,1000);};
  const poll=function(){
    if(busy || document.hidden){schedule();return;}
    busy=true;
    fetch('/api/admin/shipment-payment-requests?ts='+Date.now(),{credentials:'same-origin',cache:'no-store',headers:{'Cache-Control':'no-cache'}})
      .then(function(r){if(!r.ok)throw new Error('request failed');return r.json();})
      .then(function(data){
        if(!data || !data.ok || !Array.isArray(data.requests))return;
        const sig=signature(data.requests);
        if(sig!==lastSignature){
          const scrollBox=body.parentElement;
          const scrollTop=scrollBox ? scrollBox.scrollTop : 0;
          body.innerHTML=renderRows(data.requests);
          lastSignature=sig;
          if(scrollBox)scrollBox.scrollTop=scrollTop;
          if(indicator)indicator.textContent='● Live';
        }
      })
      .catch(function(){if(indicator)indicator.textContent='● Reconnecting…';})
      .finally(function(){busy=false;schedule();});
  };
  document.addEventListener('visibilitychange',function(){if(!document.hidden)poll();});
  poll();
})();
</script>'''
    return layout("Shipment Payment Management",body)

@app.route("/admin/payment-detail-requests/<int:payment_id>", methods=["GET","POST"])
def admin_payment_detail_request(payment_id):
    if not admin_required(): return redirect(url_for("login"))
    conn=db(); row=conn.execute("""SELECT p.*,s.tracking_id,s.currency,s.receiver_name,s.receiver_email,s.customer_id,r.id AS detail_request_id,r.method AS detail_method,r.status AS detail_status,r.requested_at,r.responded_at,r.details_json,r.image_path FROM payments p JOIN shipments s ON s.id=p.shipment_id LEFT JOIN payment_detail_requests r ON r.payment_id=p.id WHERE p.id=?""",(payment_id,)).fetchone()
    if not row: conn.close(); return redirect(url_for("admin_shipment_payment_requests"))
    method=str(row["detail_method"] or row["method"] or "").strip()
    if method not in PAYMENT_DETAIL_REQUEST_METHODS: conn.close(); return redirect(url_for("admin_shipment_payment_request",payment_id=payment_id))
    if request.method=="POST":
        details={"account":str(request.form.get("account","") or "").strip(),"instructions":str(request.form.get("instructions","") or "").strip()}
        if method=="Wire Transfer":
            details={k:str(request.form.get(k,"") or "").strip() for k in ["bank_name","beneficiary_name","account_number","iban","swift_bic","routing_number","bank_address","beneficiary_address","payment_reference"]}; details["instructions"]=str(request.form.get("instructions","") or "").strip()
        if method!="Wire Transfer" and not details["account"]: conn.close(); flash(f"Enter the {method} payment account or handle before saving."); return redirect(url_for("admin_payment_detail_request",payment_id=payment_id))
        image_path=str(row["image_path"] or "").strip(); upload=request.files.get("payment_image")
        if upload and upload.filename:
            ext=secure_filename(upload.filename).rsplit(".",1)[-1].lower() if "." in upload.filename else ""
            if ext not in {"jpg","jpeg","png","webp","gif"}: conn.close(); flash("Please upload a JPG, PNG, WEBP or GIF payment image."); return redirect(url_for("admin_payment_detail_request",payment_id=payment_id))
            os.makedirs(PAYMENT_UPLOAD_DIR,exist_ok=True); filename=f"payment_details_{payment_id}_{secrets.token_hex(10)}.{ext}"; upload.save(os.path.join(PAYMENT_UPLOAD_DIR,filename)); image_path=f"payment_uploads/{filename}"
        now=datetime.utcnow().isoformat(); conn.execute("UPDATE payment_detail_requests SET status='Ready',responded_at=?,details_json=?,image_path=? WHERE payment_id=?",(now,json.dumps(details),image_path,payment_id)); conn.execute("UPDATE payments SET payment_status='Payment Details Ready' WHERE id=?",(payment_id,))
        create_user_notification(conn,row["customer_id"],"Payment","Payment details are ready",f"Your {method} payment details for {row['tracking_id']} are ready.",f"/shipment/{row['tracking_id']}/make-payment?payment_id={payment_id}","blue",f"payment-details-ready:{payment_id}"); conn.commit(); conn.close(); flash(f"{method} payment details saved. The customer will receive them automatically."); return redirect(url_for("admin_payment_detail_request",payment_id=payment_id))
    details=_payment_detail_payload(row); image_path=str(row["image_path"] or "").strip(); image_preview=f'<div class="admin-detail-image-preview"><img src="/static/{urllib.parse.quote(image_path,safe="/")}" alt="Current payment image"><span>Current payment image</span></div>' if image_path else ''
    def val(k): return html.escape(str(details.get(k) or ""),quote=True)
    if method=="Wire Transfer": fields=''.join(f'<label>{label}<input name="{key}" value="{val(key)}" placeholder="Enter {label.lower()}"></label>' for label,key in [("Bank Name","bank_name"),("Beneficiary / Account Name","beneficiary_name"),("Account Number","account_number"),("IBAN","iban"),("SWIFT / BIC","swift_bic"),("Routing / ABA Number","routing_number"),("Bank Address","bank_address"),("Beneficiary Address","beneficiary_address"),("Payment Reference","payment_reference")])
    else: fields=f'<label>{html.escape(method)} Account / Handle<input name="account" value="{val("account")}" placeholder="Enter {html.escape(method)} email, handle or account"></label>'
    body=f"""<div class="admin-shell payment-detail-admin-shell"><section class="admin-top-card"><div><div class="eyebrow">Payment details request</div><h1>{html.escape(method)} Payment Details</h1><p>{safe_text(row["receiver_name"] or "Receiver")} · Tracking {safe_text(row["tracking_id"])} · {safe_text(row["currency"] or "USD")} {float(row["amount"] or 0):,.2f}</p></div><a class="admin-secondary-action" href="/admin/shipment-payment-requests">← Payment Requests</a></section><section class="payment-detail-request-admin-card"><div class="payment-detail-admin-hero"><div class="payment-detail-admin-brand">{html.escape(_payment_brand_icon(method))}</div><div><span>{html.escape(method.upper())} REQUEST</span><h2>New Payment Details Request</h2><p>Enter the payment information for this specific customer request. Saving here releases it automatically to the customer.</p></div><b>{html.escape(str(row["detail_status"] or "Payment Details Requested"))}</b></div><div class="payment-detail-customer-grid"><div><span>Customer</span><strong>{safe_text(row["receiver_name"] or "Receiver")}</strong></div><div><span>Tracking</span><strong>{safe_text(row["tracking_id"])}</strong></div><div><span>Amount</span><strong>{safe_text(row["currency"] or "USD")} {float(row["amount"] or 0):,.2f}</strong></div><div><span>Requested</span><strong>{safe_text(row["requested_at"] or row["paid_at"] or "")}</strong></div></div><form method="post" enctype="multipart/form-data" class="payment-detail-admin-form"><div class="admin-form-title"><span>01</span><div><h2>{html.escape(method)} Payment Information</h2><p>These details belong only to this payment request.</p></div></div><div class="payment-detail-admin-fields">{fields}</div><label>Payment Instructions <textarea name="instructions" rows="4" placeholder="Enter instructions the customer should follow.">{html.escape(str(details.get("instructions") or ""))}</textarea></label><div class="admin-detail-upload"><label>Payment Image / QR Code <input type="file" name="payment_image" accept="image/jpeg,image/png,image/webp,image/gif"></label>{image_preview}</div><button type="submit" class="payment-detail-admin-save">Save &amp; Release Payment Details</button></form></section></div>"""
    conn.close(); return layout(f"{method} Payment Details",body)


@app.route("/admin/shipment-payment-requests/<int:payment_id>")
def admin_shipment_payment_request(payment_id):
    if not admin_required(): return redirect(url_for("login"))
    conn=db(); p=conn.execute("SELECT p.*,s.tracking_id,s.currency,s.receiver_name,s.receiver_email FROM payments p JOIN shipments s ON s.id=p.shipment_id WHERE p.id=?",(payment_id,)).fetchone(); conn.close()
    if not p: return redirect(url_for("admin_shipment_payment_requests"))
    proof_link=(f'<a href="/admin/shipment-payment-requests/{payment_id}/prepaid" class="admin-primary-action">View Prepaid Card Submission</a>' if (str(p["method"] or "").strip()=="Prepaid Card" and p["proof"]) else (f'<a href="/admin/shipment-payment-requests/{payment_id}/proof" class="admin-primary-action">View Payment Proof</a>' if p["proof"] else '<span class="admin-info-note">No proof submitted yet.</span>'))
    review_actions=''
    if str(p["payment_status"] or "").strip().lower()=="proof submitted" and p["proof"]:
        review_actions=f'''<div class="admin-payment-review-actions"><form method="post" action="/admin/payment/{payment_id}/verify" onsubmit="return confirm('Confirm this payment proof? The amount will then be applied to the shipment balance.');"><button type="submit" class="admin-primary-action">✓ Confirm Payment</button></form><form method="post" action="/admin/payment/{payment_id}/reject" onsubmit="return confirm('Reject this payment proof? The shipment balance will not change.');"><button type="submit" class="admin-danger-action">✕ Reject Payment</button></form></div>'''
