    body=f"""<div class="admin-shell"><section class="admin-top-card"><div><div class="eyebrow">Prepaid Card Submission</div><h1>{safe_text(row["tracking_id"])}</h1><p>{safe_text(row["receiver_name"] or "Receiver")} · {safe_text(row["receiver_email"] or "")}</p></div><a class="admin-secondary-action" href="/admin/shipment-payment-requests/{payment_id}">← Back</a></section><section class="admin-form-card"><div class="admin-form-title"><span>01</span><div><h2>Payment Details</h2><p>{safe_text(row["currency"])} {float(row["amount"] or 0):,.2f} · Prepaid Card · {safe_text(row["payment_status"] or "Pending")}</p></div></div><div class="admin-prepaid-details"><div><span>Card type</span><strong>{safe_text(row["card_type"] or "Not selected")}</strong></div><div><span>Card value</span><strong>{safe_text(row["currency"])} {float(row["card_value"] or 0):,.2f}</strong></div><div><span>Submission status</span><strong>{safe_text(row["prepaid_status"] or "Photo Uploaded")}</strong></div></div><div class="admin-form-title" style="margin-top:22px"><span>02</span><div><h2>Uploaded Proof Photos</h2><p>{len(files)} photo(s) submitted.</p></div></div><div class="admin-prepaid-gallery">{gallery or '<div class="admin-info-note">No photos uploaded yet.</div>'}</div>{review_actions}</section></div>"""
