@app.route("/admin/payment/<int:payment_id>/verify", methods=["POST"])
def admin_verify_payment(payment_id):
    """Confirm a submitted payment proof and then apply the receiver's payment to the shipment balance."""
    if not admin_required():
        return redirect(url_for("login"))
    conn=db()
    payment=conn.execute("SELECT * FROM payments WHERE id=?",(payment_id,)).fetchone()
    if not payment:
        conn.close(); flash("Payment not found."); return redirect(url_for("admin_shipment_payment_requests"))
    shipment=conn.execute("SELECT * FROM shipments WHERE id=?",(payment["shipment_id"],)).fetchone()
    if not shipment:
        conn.close(); flash("Shipment for this payment was not found."); return redirect(url_for("admin_shipment_payment_requests"))
    current_status=str(payment["payment_status"] or "").strip().lower()
    if current_status=="verified":
        conn.close(); flash("That payment has already been confirmed."); return redirect(url_for("admin_shipment_payment_request",payment_id=payment_id))
    if current_status!="proof submitted" or not payment["proof"]:
        conn.close(); flash("Only a submitted payment proof can be confirmed."); return redirect(url_for("admin_shipment_payment_request",payment_id=payment_id))
    amount=max(0.0,float(payment["amount"] or 0))
    total=max(0.0,float(shipment["total_amount"] or 0))
    paid=max(0.0,float(shipment["paid_amount"] or 0))
    balance=max(0.0,float(shipment["outstanding_balance"] or 0))
    applied=min(amount,balance) if balance>0 else 0.0
    new_paid=round(paid+applied,2)
    if total>0: new_paid=min(new_paid,total)
    new_balance=max(0.0,round(balance-applied,2))
    new_status="Paid in Full" if total>0 and new_balance<=0.009 else ("Balance Due" if new_paid>0 or new_balance>0 else "Unpaid")

    # A submitted proof is only a request for verification. The payment is not
    # counted anywhere until the admin confirms it. Once confirmed, apply the
    # confirmed amount to the receiver's outstanding charge lines in order so the
    # Payment Breakdown page and its PAID/UNPAID badges stay synchronized with the
    # shipment-level progress bar. Partial confirmations are supported.
    remaining_to_apply=round(applied,2)
    charge_rows=conn.execute(
        "SELECT id,amount,paid_amount FROM shipment_charge_lines "
        "WHERE shipment_id=? AND LOWER(COALESCE(responsible,''))='receiver' "
        "ORDER BY display_order,id",
        (shipment["id"],)
    ).fetchall()
    for charge in charge_rows:
        if remaining_to_apply<=0.009:
            break
        charge_amount=max(0.0,float(charge["amount"] or 0))
        charge_paid=max(0.0,float(charge["paid_amount"] or 0))
        charge_remaining=max(0.0,round(charge_amount-charge_paid,2))
        if charge_remaining<=0.009:
            continue
        charge_applied=min(remaining_to_apply,charge_remaining)
        charge_new_paid=round(charge_paid+charge_applied,2)
        charge_new_status="PAID" if charge_new_paid+0.009>=charge_amount and charge_amount>0 else "UNPAID"
        conn.execute(
            "UPDATE shipment_charge_lines SET paid_amount=?,status=? WHERE id=?",
            (charge_new_paid,charge_new_status,charge["id"])
        )
        remaining_to_apply=round(remaining_to_apply-charge_applied,2)

    conn.execute("UPDATE payments SET payment_status='Verified' WHERE id=?",(payment_id,))
    conn.execute("UPDATE payment_proof_archive SET status='Verified' WHERE id=? AND id=(SELECT id FROM payment_proof_archive WHERE payment_id=? ORDER BY id DESC LIMIT 1)",(payment_id,payment_id))
    conn.execute("UPDATE shipments SET paid_amount=?,outstanding_balance=?,payment_status=? WHERE id=?",(new_paid,new_balance,new_status,shipment["id"]))
    create_user_notification(conn,shipment["customer_id"],"Payment","Payment Received",f"Your payment of {shipment['currency']} {amount:,.2f} has been received and applied to shipment {shipment['tracking_id']}.",f"/shipment/{urllib.parse.quote(str(shipment['tracking_id']),safe='')}/payment","green",f"payment-received:{payment_id}")
    create_user_notification(conn,shipment["customer_id"],"Payment","Payment Confirmed",f"Your payment of {shipment['currency']} {amount:,.2f} for {shipment['tracking_id']} has been confirmed and applied to your shipment.",f"/shipment/{urllib.parse.quote(str(shipment['tracking_id']),safe='')}/payment","green",f"payment-confirmed:{payment_id}")
    create_user_notification(conn,shipment["customer_id"],"Payment","Receipt Ready",f"Your payment receipt for shipment {shipment['tracking_id']} is ready to download.",f"/shipment/{urllib.parse.quote(str(shipment['tracking_id']),safe='')}/payment/receipt?view=1","green",f"receipt-ready:{payment_id}")
    if new_balance>0.009:
        create_user_notification(conn,shipment["customer_id"],"Payment","Outstanding Balance",f"Your shipment {shipment['tracking_id']} still has an outstanding balance of {shipment['currency']} {new_balance:,.2f}.",f"/shipment/{shipment['tracking_id']}/payment","red",f"outstanding-balance:{shipment['id']}:{new_balance:.2f}")
    conn.commit(); conn.close()
    if applied+0.009 < amount:
        flash(f"Payment confirmed. {shipment['currency']} {applied:,.2f} was applied because that was the remaining balance.")
    else:
        flash("Payment confirmed and shipment payment balance updated.")
    return redirect(url_for("admin_shipment_payment_request",payment_id=payment_id))


@app.route("/admin/payment/<int:payment_id>/reject", methods=["POST"])
def admin_reject_payment(payment_id):
    """Reject a submitted payment proof without changing the shipment balance."""
    if not admin_required():
        return redirect(url_for("login"))
    conn=db()
    payment=conn.execute("SELECT * FROM payments WHERE id=?",(payment_id,)).fetchone()
    if not payment:
        conn.close(); flash("Payment not found."); return redirect(url_for("admin_shipment_payment_requests"))
    current_status=str(payment["payment_status"] or "").strip().lower()
    if current_status=="verified":
        conn.close(); flash("A confirmed payment cannot be rejected."); return redirect(url_for("admin_shipment_payment_request",payment_id=payment_id))
    if current_status!="proof submitted" or not payment["proof"]:
        conn.close(); flash("Only a submitted payment proof can be rejected."); return redirect(url_for("admin_shipment_payment_request",payment_id=payment_id))
    conn.execute("UPDATE payments SET payment_status='Rejected' WHERE id=?",(payment_id,))
    conn.execute("UPDATE payment_proof_archive SET status='Rejected' WHERE id=? AND id=(SELECT id FROM payment_proof_archive WHERE payment_id=? ORDER BY id DESC LIMIT 1)",(payment_id,payment_id))
    shipment=conn.execute("SELECT * FROM shipments WHERE id=?",(payment["shipment_id"],)).fetchone()
    if shipment:
        create_user_notification(conn,shipment["customer_id"],"Payment","Payment proof rejected",f"Your payment proof for {shipment['tracking_id']} was rejected. You can submit a new proof.",f"/shipment/{shipment['tracking_id']}/make-payment?payment_id={payment_id}","red",f"payment-rejected:{payment_id}")
    conn.commit(); conn.close()
    flash("Payment proof rejected. The receiver can submit a new proof.")
    return redirect(url_for("admin_shipment_payment_request",payment_id=payment_id))


@app.route("/admin/shipment/<tracking_id>/tracking-toggle", methods=["POST"])
def admin_toggle_tracking(tracking_id):
    if not admin_required(): return redirect(url_for("login"))
    conn=db()
    shipment=conn.execute("SELECT id,tracking_id,tracking_enabled FROM shipments WHERE tracking_id=?",(tracking_id,)).fetchone()
    if not shipment:
        conn.close(); flash("Tracking code not found."); return redirect(url_for("admin_profile"))
    new_value=0 if int(shipment["tracking_enabled"] if shipment["tracking_enabled"] is not None else 1)==1 else 1
    conn.execute("UPDATE shipments SET tracking_enabled=? WHERE id=?",(new_value,shipment["id"]))
    conn.commit(); conn.close()
    flash(f"Tracking code {tracking_id} is now {'enabled' if new_value else 'disabled'}.")
    return redirect(request.form.get("return_to") or url_for("admin_profile"))


@app.route("/admin/shipment/<tracking_id>/delete", methods=["POST"])
def admin_delete_tracking(tracking_id):
    if not admin_required(): return redirect(url_for("login"))
    conn=db()
    shipment=conn.execute("SELECT id,tracking_id FROM shipments WHERE tracking_id=?",(tracking_id,)).fetchone()
    if not shipment:
        conn.close(); flash("Tracking code not found. It may already have been deleted."); return redirect(url_for("admin_profile"))
    shipment_id=shipment["id"]
    try:
        for table in ("tracking_events","package_items","route_stops","payments","shipment_charge_lines","documents"):
            conn.execute(f"DELETE FROM {table} WHERE shipment_id=?",(shipment_id,))
        conn.execute("DELETE FROM shipments WHERE id=?",(shipment_id,))
        conn.commit()
        flash(f"Tracking code {tracking_id} and its shipment history have been permanently deleted.")
    except Exception as exc:
        conn.rollback(); flash("The tracking code could not be deleted: "+str(exc))
    finally:
        conn.close()
    return redirect(request.form.get("return_to") or url_for("admin_profile"))


@app.route("/admin/payment-proofs")
def admin_payment_proofs():
    if not admin_required(): return redirect(url_for("login"))
    selected=str(request.args.get("method") or "All").strip()
    conn=db()
    rows=conn.execute('''SELECT a.*,s.tracking_id,s.receiver_name,s.receiver_email,s.currency AS shipment_currency
        FROM payment_proof_archive a JOIN shipments s ON s.id=a.shipment_id
        ORDER BY a.submitted_at DESC,a.id DESC''').fetchall()
    conn.close()

    categories=["All","Bitcoin","USDT (Tether)","USDC","Ethereum","Prepaid Card","Cash App","Zelle","Venmo","Other"]
    proof_archive_methods={"Bitcoin","USDT (Tether)","USDC","Ethereum","Prepaid Card","Cash App","Zelle","Venmo"}
    counts={k:0 for k in categories}
    for row in rows:
        m=str(row["method"] or "Other").strip()
        if m in proof_archive_methods: counts[m]+=1
        else: counts["Other"]+=1
    if selected not in categories: selected="All"
    filtered=[]
    for row in rows:
        method=str(row["method"] or "Other").strip()
        bucket=method if method in proof_archive_methods else "Other"
        if selected=="All" or selected==bucket: filtered.append(row)

    tabs=[]
    for category in categories:
        count=len(rows) if category=="All" else counts[category]
        href="/admin/payment-proofs" if category=="All" else "/admin/payment-proofs?method="+urllib.parse.quote(category)
        active=" active" if selected==category else ""
        tabs.append(f'<a class="{active.strip()}" href="{href}">{html.escape(category)} <span class="payment-proof-archive-count">{count}</span></a>')

    cards=[]
    for row in filtered:
        method=str(row["method"] or "Other").strip()
        status=str(row["status"] or "Proof Submitted").strip()
        low=status.lower()
        status_class="confirmed" if low in {"verified","confirmed"} else ("rejected" if low=="rejected" else "pending")
        try: files=json.loads(row["proof_filenames"] or "[]")
        except Exception: files=[]
        files=list(dict.fromkeys(str(x) for x in files if str(x).strip()))
        if not files: files=[]
        gallery_parts=[]
        for idx,path in enumerate(files,1):
            if path.startswith("payment_uploads/"):
                url="/static/"+urllib.parse.quote(path,safe="/")
                download_name="payment_proof_"+str(row['id'])+"_"+str(idx)+"."+(path.rsplit(".",1)[-1] if "." in path else "jpg")
                gallery_parts.append(f'<div class="payment-proof-item"><a href="{url}" target="_blank" rel="noopener"><img src="{url}" alt="{html.escape(method)} payment proof {idx}"></a><div class="payment-proof-item-actions"><a href="{url}" target="_blank" rel="noopener" class="secondary">View</a><a href="{url}" download="{html.escape(download_name,quote=True)}">Save</a></div></div>')
            else:
                gallery_parts.append(f'<div class="payment-proof-text-proof">{safe_text(path)}</div>')
        gallery=''.join(gallery_parts) or '<div class="payment-proof-empty">No image file is attached to this archived proof.</div>'
        review_actions=""
        if low in {"proof submitted","pending","awaiting method","method selected"}:
            review_actions=f'''<div class="payment-proof-review-actions"><form method="post" action="/admin/payment/{int(row['payment_id'])}/verify" onsubmit="return confirm('Confirm this payment proof? The amount will then be applied to the shipment balance.');"><button type="submit" class="admin-primary-action">✓ Confirm Payment</button></form><form method="post" action="/admin/payment/{int(row['payment_id'])}/reject" onsubmit="return confirm('Reject this payment proof? The proof will remain saved in the archive.');"><button type="submit" class="admin-danger-action">✕ Reject Payment</button></form></div>'''
        elif low in {"verified","confirmed"}:
            review_actions='<div class="admin-info-note" style="margin-top:12px">✓ This payment has been confirmed. The proof remains permanently available here.</div>'
        elif low=="rejected":
            review_actions='<div class="admin-info-note" style="margin-top:12px">✕ This proof was rejected. It remains saved here for your payment history.</div>'
        submitted=str(row["submitted_at"] or "")
        cards.append(f'''<article class="payment-proof-archive-card"><div class="payment-proof-archive-head"><div class="payment-proof-archive-title"><strong>{safe_text(method)} · {safe_text(row["tracking_id"])}</strong><span>{safe_text(row["receiver_name"] or "Receiver")} · {safe_text(row["receiver_email"] or "")}</span></div><span class="payment-proof-status {status_class}">{safe_text(status)}</span></div><div class="payment-proof-archive-meta"><div><span>Amount</span><strong>{safe_text(row["currency"] or row["shipment_currency"] or "USD")} {float(row["amount"] or 0):,.2f}</strong></div><div><span>Submitted</span><strong>{safe_text(submitted)}</strong></div><div><span>Tracking</span><strong>{safe_text(row["tracking_id"])}</strong></div><div><span>Proof files</span><strong>{len(files)}</strong></div></div><div class="payment-proof-gallery">{gallery}</div>{review_actions}</article>''')
    content=''.join(cards) or '<div class="payment-proof-empty">No payment proofs have been submitted in this category yet.</div>'
    body=f'''<div class="admin-shell"><section class="admin-top-card"><div><div class="eyebrow">Payment records</div><h1>Payment Proof Archive</h1><p>All submitted payment proofs stay here after confirmation or rejection, arranged newest first.</p></div><div class="admin-top-actions"><a class="admin-secondary-action" href="/admin/shipment-payment-requests">Payment Management</a><a class="admin-secondary-action" href="/admin">← Dashboard</a></div></section><section class="admin-section"><div class="payment-proof-archive-note"><strong>Saved proof history:</strong> Confirming or rejecting a payment does not remove its proof. Use the method tabs to view Bitcoin, USDT, USDC, Ethereum, Prepaid Card, Cash App, Zelle, Venmo or other proof records. Cash App, Zelle and Venmo proofs use the same View, Save, Confirm and Reject controls as the existing payment methods. Every image has its own Save button.</div><div class="payment-proof-archive-tabs">{''.join(tabs)}</div>{content}</section></div>'''
    return layout("Payment Proof Archive",body)


@app.route("/api/user/notifications")
def user_notifications_api():
    u=current_user()
    if u and u["role"]=="admin": return jsonify({"ok":False,"error":"Unauthorized"}),401
    tracking_id=str(request.args.get("tracking_id") or _receiver_tracking_id()).strip()
    if not u and not tracking_id: return jsonify({"ok":False,"error":"Tracking number is required."}),401
    try: limit=max(1,min(int(request.args.get("limit") or 40),100))
    except (TypeError,ValueError): limit=40
    # Logged-in receiver notifications are account-level. The currently open
    # shipment must never hide a valid notification for that same account.
    if u:
        owner_id=int(u["id"])
    else:
        s=get_shipment(tracking_id)
        if not s or not s["customer_id"]: return jsonify({"ok":True,"notifications":[],"unread_count":0})
        owner_id=int(s["customer_id"])
    response=jsonify(_user_notification_payload(owner_id,limit,tracking_id)); response.headers["Cache-Control"]="no-store, no-cache, must-revalidate, max-age=0"; response.headers["Pragma"]="no-cache"; return response

@app.route("/api/user/notifications/<int:notification_id>/read",methods=["POST"])
def user_notification_mark_read(notification_id):
    u=current_user()
    if u and u["role"]=="admin": return jsonify({"ok":False,"error":"Unauthorized"}),401
    tracking_id=str(request.args.get("tracking_id") or _receiver_tracking_id()).strip()
    if u:
        # An authenticated receiver can mark only their own notification read.
        # Do not restrict this by the shipment currently open in the browser.
        conn=db(); conn.execute("UPDATE user_notifications SET is_read=1 WHERE id=? AND user_id=?",(notification_id,u["id"])); conn.commit(); conn.close(); return jsonify({"ok":True})
    if not tracking_id: return jsonify({"ok":False,"error":"Tracking number is required."}),401
    s=get_shipment(tracking_id)
    if not s or not s["customer_id"]: return jsonify({"ok":False,"error":"Unauthorized"}),403
    owner_id=int(s["customer_id"])
    conn=db(); conn.execute("UPDATE user_notifications SET is_read=1 WHERE id=? AND user_id=?",(notification_id,owner_id)); conn.commit(); conn.close(); return jsonify({"ok":True})

@app.route("/api/user/notifications/mark-all-read",methods=["POST"])
def user_notifications_mark_all_read():
    u=current_user()
    if u and u["role"]=="admin": return jsonify({"ok":False,"error":"Unauthorized"}),401
    tracking_id=str(request.args.get("tracking_id") or _receiver_tracking_id()).strip()
    if u:
        # Mark every notification belonging to this authenticated receiver.
        # The current shipment must not limit the notification center.
        conn=db(); conn.execute("UPDATE user_notifications SET is_read=1 WHERE user_id=? AND is_read=0",(u["id"],)); conn.commit(); conn.close(); return jsonify({"ok":True})
    if not tracking_id: return jsonify({"ok":False,"error":"Tracking number is required."}),401
    s=get_shipment(tracking_id)
    if not s or not s["customer_id"]: return jsonify({"ok":False,"error":"Unauthorized"}),403
    owner_id=int(s["customer_id"])
    conn=db(); conn.execute("UPDATE user_notifications SET is_read=1 WHERE user_id=? AND is_read=0",(owner_id,)); conn.commit(); conn.close(); return jsonify({"ok":True})

@app.route("/api/tracking-presence",methods=["POST"])
def tracking_presence_api():
    payload=request.get_json(silent=True) or {}
    tracking_id=str(payload.get("tracking_id") or "").strip()
    if not tracking_id: return jsonify({"ok":False,"error":"Tracking number is required."}),400
    s=get_shipment(tracking_id)
    if not s or not tracking_available(s): return jsonify({"ok":False,"error":"Tracking unavailable."}),404
    conn=db(); state=record_tracking_presence(conn,s,notify=True); conn.commit(); conn.close()
    return jsonify({"ok":True,"state":state,"tracking_id":tracking_id})

@app.route("/api/tracking-presence/offline",methods=["POST"])
def tracking_presence_offline_api():
    payload=request.get_json(silent=True) or {}
    tracking_id=str(payload.get("tracking_id") or "").strip()
    if not tracking_id: return jsonify({"ok":False,"error":"Tracking number is required."}),400
    token=_tracking_visitor_token()
    conn=db()
    row=conn.execute("SELECT id,tracking_id,is_live FROM tracking_presence WHERE visitor_token=?",(token,)).fetchone()
    if row and str(row["tracking_id"] or "") == tracking_id and int(row["is_live"] or 0)==1:
        now=datetime.utcnow().isoformat()
        conn.execute("UPDATE tracking_presence SET is_live=0,last_offline_at=? WHERE visitor_token=?",(now,token))
        conn.commit()
    conn.close()
    return jsonify({"ok":True,"tracking_id":tracking_id,"state":"offline"})

@app.route("/api/admin/live-tracking")
def admin_live_tracking_api():
    if not admin_required(): return jsonify({"ok":False,"error":"Unauthorized"}),401
    conn=db()
    rows=conn.execute("SELECT p.tracking_id,p.customer_id,p.first_seen,p.last_seen,p.is_live,p.last_offline_at,s.receiver_name,s.status FROM tracking_presence p LEFT JOIN shipments s ON s.tracking_id=p.tracking_id WHERE s.id IS NOT NULL ORDER BY p.last_seen DESC LIMIT 200").fetchall()
    now=datetime.utcnow()
    latest_by_tracking={}
    for r in rows:
        tracking_id=str(r["tracking_id"] or "").strip()
        if not tracking_id: continue
        if tracking_id not in latest_by_tracking:
            latest_by_tracking[tracking_id]=r

    result=[]
    for tracking_id,r in latest_by_tracking.items():
        try: last=datetime.fromisoformat(str(r["last_seen"] or "")); seconds=max(0,int((now-last).total_seconds()))
        except Exception: seconds=999999
        stored_live=int(r["is_live"] or 0)==1
        # The admin panel is green only while the visitor is truly live.
        # The client displays "Just now" for 0-9 seconds, so keep Live now
        # strictly within that same window. Once the counter becomes seconds/minutes ago, go offline.
        live=stored_live and seconds<10
        if live and not stored_live:
            conn.execute("UPDATE tracking_presence SET is_live=1 WHERE tracking_id=? AND last_seen=?",(tracking_id,str(r["last_seen"] or "")))
        elif not live and stored_live:
            conn.execute("UPDATE tracking_presence SET is_live=0,last_offline_at=? WHERE tracking_id=? AND last_seen=?",(now.isoformat(),tracking_id,str(r["last_seen"] or "")))
        result.append({"tracking_id":tracking_id,"receiver":str(r["receiver_name"] or "Receiver"),"status":str(r["status"] or "Processing"),"last_seen":str(r["last_seen"] or ""),"seconds_since_seen":seconds,"is_live":live})
    conn.commit(); conn.close()
    response=jsonify({"ok":True,"visitors":result}); response.headers["Cache-Control"]="no-store, no-cache, must-revalidate, max-age=0"; response.headers["Pragma"]="no-cache"; return response

@app.route("/api/admin/user-activity", methods=["POST"])
def admin_user_activity_api():
    """Record receiver-side click activity for the Admin notification center.

    Activity is tied to a registered shipment rather than requiring a logged-in
    customer session. This is important because the receiver can enter a
    shipment through its tracking number without signing in, while the admin
    still needs to see who performed the action.
    """
    data=request.get_json(silent=True) or request.form
    action=str(data.get("action") or "clicked").strip()[:120]
    page=str(data.get("page") or "YS Logistics").strip()[:160]
    target=str(data.get("target") or request.path or "/").strip()[:500]
    label=str(data.get("label") or "Click").strip()[:160]
    tracking_id=str(data.get("tracking_id") or "").strip()[:120]
    if not action or not label:
        return jsonify({"ok":False,"error":"Missing activity details"}),400

    user=current_user()
    if user and user["role"]=="admin":
        return jsonify({"ok":False,"error":"Unauthorized"}),401

    conn=db()
    shipment=None
    if tracking_id:
        shipment=conn.execute("SELECT * FROM shipments WHERE tracking_id=? LIMIT 1",(tracking_id,)).fetchone()
    if not shipment:
        # Do not create anonymous/global activity records. The notification
        # feature is only for actions performed inside a registered shipment.
        conn.close()
        return jsonify({"ok":False,"error":"Registered shipment required"}),404

    if not tracking_id:
        tracking_id=str(shipment["tracking_id"] or "")
    name=""
    if user and user["role"]!="admin":
        name=str(user["name"] or user["email"] or "").strip()
    if not name:
        name=str(shipment["receiver_name"] or "A receiver").strip() or "A receiver"

    if action=="opened":
        clean_label=label.replace("opened","").replace("Opened","").strip(" -")
        message=f"{name} clicked {clean_label or 'the page'}."
        title=clean_label or "Click"
    elif action=="back":
        message=f"{name} {label}."
        title=label
    elif action=="cancel":
        message=f"{name} {label}."
        title=label
    else:
        message=f"{name} {label}."
        title=label
    message += f" Shipment {tracking_id}."
    create_admin_notification(conn,"User Activity",title,message,admin_notification_view_url(target,"User Activity",title),"blue",None)
    conn.commit(); conn.close()
    return jsonify({"ok":True})

