@app.route("/admin/notification-recycle-bin")
def admin_notification_recycle_bin():
    if not admin_required(): return redirect(url_for("login"))
    conn=db(); cleanup_admin_notification_recycle_bin(conn); conn.commit()
    rows=conn.execute("SELECT * FROM admin_notification_recycle_bin ORDER BY archived_at DESC,id DESC").fetchall(); conn.close()
    cards=[]
    for row in rows:
        try:
            expires=datetime.fromisoformat(str(row["expires_at"] or "")); days_left=max(0,(expires-datetime.utcnow()).total_seconds()/86400)
            retention=f"Permanent deletion in {max(1,int(days_left+0.999))} day" if days_left>0 else "Scheduled for permanent deletion"
        except Exception: retention="Scheduled for permanent deletion"
        rid=int(row["id"]); category=safe_text(row["category"] or "General"); archived=safe_text(row["archived_at"] or ""); title=safe_text(row["title"] or "Notification"); message=safe_text(row["message"] or ""); ret=safe_text(retention)
        cards.append(f'<article class="admin-recycle-item"><div class="admin-recycle-copy"><div class="admin-recycle-meta"><span>{category}</span><small>Archived {archived}</small></div><h3>{title}</h3><p>{message}</p><small>{ret}</small></div><div class="admin-recycle-actions"><form method="post" action="/admin/notification-recycle-bin/{rid}/restore"><button class="admin-primary-action" type="submit">↩ Restore</button></form><form method="post" action="/admin/notification-recycle-bin/{rid}/delete" onsubmit="return confirm(\'Permanently delete this notification?\')"><button class="admin-danger-action" type="submit">Delete Permanently</button></form></div></article>')
    body="<div class=\"admin-shell\"><section class=\"admin-top-card\"><div><div class=\"eyebrow\">Admin Notifications</div><h1>Notification Recycle Bin</h1><p>Notifications older than 24 hours are moved here automatically. Items remain here for 3 days before permanent deletion.</p></div><a class=\"admin-secondary-action\" href=\"/admin/profile\">← Admin Profile</a></section><section class=\"admin-form-card\"><div class=\"admin-form-title\"><span>♻</span><div><h2>Archived Notifications</h2><p>Restore a notification to the active notification list, or permanently delete it now.</p></div></div><div class=\"admin-recycle-list\">" + ("".join(cards) or "<div class=\"admin-empty\">The recycle bin is empty.</div>") + "</div></section></div>"
    return layout("Notification Recycle Bin",body)

@app.route("/admin/notification-recycle-bin/<int:recycle_id>/restore",methods=["POST"])
def admin_notification_recycle_restore(recycle_id):
    if not admin_required(): return redirect(url_for("login"))
    conn=db(); cleanup_admin_notification_recycle_bin(conn); row=conn.execute("SELECT * FROM admin_notification_recycle_bin WHERE id=?",(recycle_id,)).fetchone()
    if row:
        conn.execute("INSERT INTO admin_notifications(category,title,message,url,severity,created_at,is_read,dedupe_key) VALUES(?,?,?,?,?,?,?,?)",(row["category"],row["title"],row["message"],row["url"],row["severity"],row["created_at"],row["is_read"],row["dedupe_key"]))
        conn.execute("DELETE FROM admin_notification_recycle_bin WHERE id=?",(recycle_id,)); flash("Notification restored to Admin Notifications.")
    else: flash("That notification is no longer in the recycle bin.")
    conn.commit(); conn.close(); return redirect(url_for("admin_notification_recycle_bin"))

