def ensure_generated_qr(value, method_key):
    """Return an uploaded QR path when available. QR generation is intentionally optional.

    The receiver page always shows its QR area. Administrators can upload the exact
    QR image from Admin Profile, so the application does not require the external
    ``qrcode`` Python package just to start the Flask server.
    """
    return ""


PAYMENT_METHOD_AVAILABILITY_KEYS={"bitcoin":"payment_method_available_bitcoin","usdt":"payment_method_available_usdt","ethereum":"payment_method_available_ethereum","paypal":"payment_method_available_paypal","cash-app":"payment_method_available_cash-app","zelle":"payment_method_available_zelle","venmo":"payment_method_available_venmo","wire-transfer":"payment_method_available_wire-transfer"}
def payment_method_is_available(conn,method_key):
    key=PAYMENT_METHOD_AVAILABILITY_KEYS.get(method_key)
    if not key:return True
    row=conn.execute("SELECT setting_value FROM admin_settings WHERE setting_key=?",(key,)).fetchone()
    return (not row) or str(row["setting_value"] or "1").strip().lower() not in {"0","false","no","off","unavailable"}

@app.route("/admin/payment-method/<method_key>/save", methods=["POST"])
def admin_payment_method_save(method_key):
    if not admin_required(): return redirect(url_for("login"))
    specs={
        "bitcoin":("Bitcoin","bitcoin_payment_address","bitcoin_qr_image"),
        "usdt":("USDT (Tether)","usdt_payment_address","usdt_qr_image"),
        "ethereum":("Ethereum","ethereum_payment_address","ethereum_qr_image"),
        "paypal":("PayPal","paypal_payment_details","paypal_payment_image"),
        "cash-app":("Cash App","cash_app_payment_details","cash_app_payment_image"),
        "zelle":("Zelle","zelle_payment_details","zelle_payment_image"),
        "venmo":("Venmo","venmo_payment_details","venmo_payment_image"),
        "wire-transfer":("Wire Transfer","wire_transfer_payment_details","wire_transfer_payment_image"),
    }
    spec=specs.get(method_key)
    if not spec:
        flash("Payment method could not be found.")
        return redirect(url_for("admin_profile"))
    label,detail_key,image_key=spec
    conn=db()
    try:
        availability_key=PAYMENT_METHOD_AVAILABILITY_KEYS.get(method_key)
        availability_value="1" if request.form.get("availability","available")=="available" else "0"
        if availability_key:
            conn.execute("INSERT INTO admin_settings(setting_key,setting_value) VALUES(?,?) ON CONFLICT(setting_key) DO UPDATE SET setting_value=excluded.setting_value",(availability_key,availability_value))
        if method_key=="wire-transfer":
            wire_keys=[
                "wire_transfer_bank_name","wire_transfer_beneficiary_name","wire_transfer_account_number",
                "wire_transfer_iban","wire_transfer_swift_bic","wire_transfer_routing_number",
                "wire_transfer_bank_address","wire_transfer_beneficiary_address","wire_transfer_payment_reference"
            ]
            for key in wire_keys:
                value=str(request.form.get(key,"") or "").strip()
                conn.execute("INSERT INTO admin_settings(setting_key,setting_value) VALUES(?,?) ON CONFLICT(setting_key) DO UPDATE SET setting_value=excluded.setting_value",(key,value))
            conn.commit()
            flash("Wire Transfer settings saved. They are now available on the customer payment page.")
            return redirect(url_for("admin_profile"))
        detail=str(request.form.get("payment_detail","") or "").strip()
        conn.execute("INSERT INTO admin_settings(setting_key,setting_value) VALUES(?,?) ON CONFLICT(setting_key) DO UPDATE SET setting_value=excluded.setting_value",(detail_key,detail))
        upload=request.files.get("payment_image")
        if upload and upload.filename:
            ext=secure_filename(upload.filename).rsplit(".",1)[-1].lower() if "." in upload.filename else ""
            if ext not in {"png","jpg","jpeg","webp","gif"}:
                conn.rollback(); flash(f"{label} images must be PNG, JPG, JPEG, WEBP or GIF.")
                return redirect(url_for("admin_profile"))
            os.makedirs(QR_UPLOAD_DIR,exist_ok=True)
            old_row=conn.execute("SELECT setting_value FROM admin_settings WHERE setting_key=?",(image_key,)).fetchone()
            old_path=str(old_row["setting_value"] if old_row else "")
            filename=f"{method_key.replace('-', '_')}_payment_{secrets.token_hex(8)}.{ext}"
            upload.save(os.path.join(QR_UPLOAD_DIR,filename))
            new_path=f"payment_qr/{filename}"
            conn.execute("INSERT INTO admin_settings(setting_key,setting_value) VALUES(?,?) ON CONFLICT(setting_key) DO UPDATE SET setting_value=excluded.setting_value",(image_key,new_path))
            if old_path.startswith("payment_qr/"):
                old_file=os.path.join(BASE_DIR,"static",old_path.replace("/",os.sep))
                if os.path.isfile(old_file):
                    try: os.remove(old_file)
                    except OSError: pass
        conn.commit(); flash(f"{label} payment settings saved.")
    except Exception as exc:
        conn.rollback(); flash(f"{label} payment settings could not be saved: {exc}")
    finally:
        conn.close()
    return redirect(url_for("admin_profile"))


